import Texture2D from "monks-webgpu/renderer/texture/Texture2D";
import Renderer from "monks-webgpu/renderer/render/Renderer";
import IPreloadable from "monks-webgpu/renderer/core/IPreloadable";
import WebGPUPreLoader from "monks-webgpu/renderer/core/WebGPUPreLoader";
import decodePngRgba8 from "monks-webgpu/utils/image/decodePngRgba8";
import blueNoise2D16Bits from "./blueNoise2D16Bits.png";

/**
 * Loads the 2 channel blue noise of BlueNoise2DGenerator, generated by tools/blueNoise2D/generate.ts: the (x, y) of
 * neighbouring pixels are far apart as 2d points. For 2d samples, where BlueNoiseTexture16Bits is blue per channel only.
 * The PNG stores 2 16-bit values in its 4 channels: R, G = high and low byte of x, B, A = high and low byte of y.
 * Decoded with decodePngRgba8, as a canvas would premultiply the alpha. Uploaded as an rg16unorm texture
 */
export default class BlueNoiseTexture2D16Bits extends Texture2D implements IPreloadable {

  constructor(renderer: Renderer, preLoader: WebGPUPreLoader) {
    super(renderer, 256, 256);
    preLoader.add(this);
  }

  public load(callback: () => void): void {
    this.loadPng().then(callback);
  }

  private async loadPng(): Promise<void> {
    const response = await fetch(blueNoise2D16Bits);
    const {width, height, data} = await decodePngRgba8(await response.arrayBuffer());

    const pixelCount = width * height;
    const pixelData = new Uint16Array(pixelCount * 2);
    for (let i = 0; i < pixelCount; i++) {
      const offset = i * 4;
      pixelData[i * 2] = (data[offset] << 8) | data[offset + 1];
      pixelData[i * 2 + 1] = (data[offset + 2] << 8) | data[offset + 3];
    }

    this.setData(pixelData, width, height, 'rg16unorm');
  }
}
